from config.schema_types import BOOL, CENTS, DATE, INT, TEXT, TIME, UUID, choice, nullable, obj, op, parameter, ref

SCHEMAS = {
    "CheckoutLink": obj({"payment_id": UUID, "checkout_url": TEXT, "expires_at": nullable(TIME), "status": TEXT}),
    "PaymentReview": obj({"loan_id": UUID, "mode": choice("installment", "payoff", "partial"), "amount": CENTS, "principal_balance": CENTS, "accrued_interest": CENTS, "payoff_amount": CENTS, "next_installment_due": CENTS, "next_due_date": nullable(DATE), "currency": choice("PHP"), "test_mode": BOOL, "allocation_note": TEXT}),
}
OPERATIONS = {
    ("PaymentPreviewView", "GET"): op(ref("PaymentReview"), summary="Review the borrower's current payable amount", parameters=[parameter("mode", choice("installment", "payoff", "partial")), parameter("amount", CENTS, "Required for partial mode only.")], description="Read-only, borrower-only. Accrued payoff excludes future interest. The checkout endpoint rechecks payable state."),
    ("CheckoutView", "POST"): op(ref("CheckoutLink"), obj({"operation_id": UUID, "mode": choice("installment", "payoff", "partial"), "requested_amount": CENTS}, ["operation_id"]), summary="Request server-routed borrower checkout", description="Never supply payer, payment version, route or arbitrary amount. Only partial mode accepts requested_amount. A checkout redirect is not confirmation of collection or settlement."),
    ("CommissionCheckoutView", "POST"): op(ref("CheckoutLink"), obj({"operation_id": UUID}), summary="Request the lender's origination-fee checkout", description="Lender-only. Server determines fee amount and routing. Fee is separate from borrower repayments."),
    ("WebhookView", "POST"): op(obj({"inbox_id": UUID,"state": TEXT}), obj({}), status=202, summary="Receive a signed PixelFlow callback", description="Service integration, not a browser operation. Raw body signature and Pixelflow-Event-ID are checked against the configured routing ID. Duplicate events are recorded without duplicate ledger effects. Full provider payload variants remain partial; never send a browser CSRF token or invent a signature.", partial=True),
}

SCHEMAS["PixelFlowEvent"]=obj({"id":TEXT,"api_version":choice("2026-10-24"),"environment":choice("test","live"),"project_id":TEXT,"tenant_id":TEXT,"type":TEXT,"created_at":TIME,"data":obj({"id":TEXT,"external_id":TEXT,"amount":{**CENTS,"minimum":1},"currency":choice("PHP"),"version":{**INT,"minimum":1},"payable_version":TEXT,"paid_at":TIME},["id","external_id","amount","currency","version","payable_version"]),"refund":obj({"id":TEXT,"amount":{**CENTS,"minimum":1},"succeeded_at":TIME,"updated_at":TIME},["id","amount"])},["id","api_version","environment","project_id","tenant_id","type","data"])
OPERATIONS[("WebhookView","POST")]=op(obj({"inbox_id":UUID,"state":TEXT}),ref("PixelFlowEvent"),status=202,summary="Receive an authenticated PixelFlow event",description="Raw-body HMAC-SHA256 signature uses Pixelflow-Signature t=timestamp,v1=digest and matching Pixelflow-Event-ID; five-minute tolerance. Server-owned route requires approved test scope, project/tenant/version/amount matching. payment.succeeded requires authoritative paid_at; refund.succeeded/payment.refunded require immutable refund identity/amount and a valid effective timestamp. Other event types may be recorded as evidence_only. Duplicate identity with changed payload returns 409. No browser CSRF or secret belongs in this request.")
OPERATIONS[("WebhookView","POST")]["headers"]=[{"name":"Pixelflow-Signature","in":"header","required":True,"schema":TEXT,"description":"Provider-generated timestamp and signature; never a browser credential."},{"name":"Pixelflow-Event-ID","in":"header","required":True,"schema":TEXT}]
